mapper.select:
SELECT t.id, t.ecs_id, t.name, t.remark, t.status, t.pay_price_text, t.pay_price_color, t.ecs_type, t.product_type, t1.cpu_number, t1.memory_size, t1.gpu_model, t1.ecs_scale, t1.hours_price, t1.month_price, t1.one_year_price, t1.two_year_price, t1.three_year_price, t1.regions_zones FROM sys_home_ecs t LEFT JOIN sys_ecs t1 ON t.ecs_id = t1.id WHERE t.del_flag = 0
AND t.name LIKE CONCAT('%',#{query.name},'%')
AND t.status = #{query.status}
AND t.product_type = #{query.productType}
order by t.create_time desc
